    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
            color: #2d2d2d;
            background-color: #fff;
            line-height: 1.6;
        }

        a {
            text-decoration: none;
            color: inherit;
        }

        img {
            display: block;
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        /* Top Bar */
        .top-bar {
            background-color: #2d2d2d;
            color: #fff;
            text-align: center;
            padding: 8px 20px;
            font-size: 13px;
            letter-spacing: 1px;
        }

        /* Header */
        header {
            background-color: #fff;
            border-bottom: 1px solid #eee;
            position: sticky;
            top: 0;
            z-index: 100;
        }

        .header-inner {
            max-width: 1440px;
            margin: 0 auto;
            padding: 0 40px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            height: 70px;
        }

        .logo {
            font-size: 28px;
            font-weight: 700;
            letter-spacing: 2px;
        }

        .logo span {
            color: #c9a96e;
        }

        nav {
            display: flex;
            gap: 32px;
        }

        nav a {
            font-size: 14px;
            letter-spacing: 1px;
            padding: 8px 0;
            border-bottom: 2px solid transparent;
            transition: all 0.3s;
        }

        nav a:hover,
        nav a.active {
            color: #c9a96e;
            border-bottom-color: #c9a96e;
        }

        .header-icons {
            display: flex;
            align-items: center;
            gap: 20px;
        }

        .header-icons a {
            display: flex;
            align-items: center;
            gap: 6px;
            font-size: 13px;
            transition: color 0.3s;
        }

        .header-icons a:hover {
            color: #c9a96e;
        }

        .cart-badge {
            background-color: #c9a96e;
            color: #fff;
            font-size: 11px;
            width: 18px;
            height: 18px;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        /* Hero */
        .hero {
            position: relative;
            height: 560px;
            overflow: hidden;
        }

        .hero img {
            width: 100%;
            height: 100%;
            object-fit: cover;
        }

        .hero-overlay {
            position: absolute;
            inset: 0;
            background: linear-gradient(to right, rgba(0,0,0,0.5) 0%, rgba(0,0,0,0.1) 60%, transparent 100%);
            display: flex;
            align-items: center;
            padding: 0 80px;
        }

        .hero-content {
            color: #fff;
            max-width: 520px;
        }

        .hero-content h1 {
            font-size: 42px;
            font-weight: 300;
            letter-spacing: 4px;
            margin-bottom: 16px;
            line-height: 1.3;
        }

        .hero-content p {
            font-size: 16px;
            opacity: 0.9;
            margin-bottom: 32px;
            line-height: 1.8;
        }

        .btn-primary {
            display: inline-block;
            padding: 14px 40px;
            background-color: #c9a96e;
            color: #fff;
            font-size: 14px;
            letter-spacing: 2px;
            border: none;
            cursor: pointer;
            transition: background-color 0.3s;
        }

        .btn-primary:hover {
            background-color: #b8944f;
        }

        /* Categories */
        .section {
            max-width: 1440px;
            margin: 0 auto;
            padding: 60px 40px;
        }

        .section-title {
            text-align: center;
            margin-bottom: 40px;
        }

        .section-title h2 {
            font-size: 28px;
            font-weight: 400;
            letter-spacing: 3px;
            margin-bottom: 8px;
        }

        .section-title p {
            font-size: 14px;
            color: #999;
        }

        .category-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 20px;
        }

        .category-card {
            position: relative;
            height: 360px;
            border-radius: 8px;
            overflow: hidden;
            cursor: pointer;
        }

        .category-card img {
            transition: transform 0.5s;
        }

        .category-card:hover img {
            transform: scale(1.05);
        }

        .category-card .overlay {
            position: absolute;
            inset: 0;
            background: linear-gradient(to top, rgba(0,0,0,0.6) 0%, transparent 50%);
            display: flex;
            align-items: flex-end;
            padding: 24px;
        }

        .category-card .overlay h3 {
            color: #fff;
            font-size: 18px;
            font-weight: 400;
            letter-spacing: 2px;
        }

        /* New Arrivals */
        .product-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 24px;
        }

        .product-card {
            cursor: pointer;
        }

        .product-card .image-wrap {
            position: relative;
            height: 320px;
            border-radius: 8px;
            overflow: hidden;
            margin-bottom: 14px;
        }

        .product-card .image-wrap img {
            transition: transform 0.5s;
        }

        .product-card:hover .image-wrap img {
            transform: scale(1.05);
        }

        .product-card .tag {
            position: absolute;
            top: 12px;
            left: 12px;
            background-color: #c9a96e;
            color: #fff;
            font-size: 11px;
            padding: 4px 10px;
            border-radius: 3px;
        }

        .product-card h4 {
            font-size: 15px;
            font-weight: 400;
            margin-bottom: 6px;
        }

        .product-card .price {
            font-size: 16px;
            color: #c9a96e;
            font-weight: 600;
        }

        .product-card .price .original {
            font-size: 13px;
            color: #aaa;
            text-decoration: line-through;
            margin-left: 8px;
            font-weight: 400;
        }

        /* Banner */
        .banner {
            background-color: #f5f0eb;
            padding: 60px 40px;
        }

        .banner-inner {
            max-width: 1440px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 40px;
            align-items: center;
        }

        .banner-text h2 {
            font-size: 32px;
            font-weight: 300;
            letter-spacing: 3px;
            margin-bottom: 16px;
        }

        .banner-text p {
            font-size: 15px;
            color: #666;
            margin-bottom: 28px;
            line-height: 1.8;
        }

        .banner-image {
            height: 360px;
            border-radius: 8px;
            overflow: hidden;
        }

        /* Features */
        .features {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 30px;
            text-align: center;
        }

        .feature-item {
            padding: 30px 20px;
        }

        .feature-item .icon {
            width: 48px;
            height: 48px;
            margin: 0 auto 16px;
            background-color: #f5f0eb;
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 20px;
        }

        .feature-item h4 {
            font-size: 15px;
            margin-bottom: 8px;
        }

        .feature-item p {
            font-size: 13px;
            color: #999;
        }

        /* Footer */
        footer {
            background-color: #2d2d2d;
            color: #fff;
            padding: 60px 40px 30px;
        }

        .footer-inner {
            max-width: 1440px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: 2fr 1fr 1fr 1fr;
            gap: 40px;
            margin-bottom: 40px;
        }

        .footer-brand .logo {
            color: #fff;
            margin-bottom: 16px;
        }

        .footer-brand p {
            font-size: 13px;
            color: #aaa;
            line-height: 1.8;
        }

        .footer-col h4 {
            font-size: 14px;
            margin-bottom: 16px;
            color: #c9a96e;
        }

        .footer-col a {
            display: block;
            font-size: 13px;
            color: #aaa;
            margin-bottom: 10px;
            transition: color 0.3s;
        }

        .footer-col a:hover {
            color: #fff;
        }

        .footer-bottom {
            max-width: 1440px;
            margin: 0 auto;
            padding-top: 30px;
            border-top: 1px solid #444;
            display: flex;
            justify-content: space-between;
            font-size: 12px;
            color: #888;
        }

        /* Responsive */
        @media (max-width: 1024px) {
            .category-grid,
            .product-grid {
                grid-template-columns: repeat(2, 1fr);
            }

            .features {
                grid-template-columns: repeat(2, 1fr);
            }

            .banner-inner {
                grid-template-columns: 1fr;
            }

            .footer-inner {
                grid-template-columns: 1fr 1fr;
            }
        }

        @media (max-width: 768px) {
            .header-inner {
                padding: 0 20px;
            }

            nav {
                display: none;
            }

            .hero {
                height: 400px;
            }

            .hero-overlay {
                padding: 0 30px;
            }

            .hero-content h1 {
                font-size: 28px;
            }

            .section {
                padding: 40px 20px;
            }

            .category-grid,
